-- Seed del contenuto (lezioni ed esercizi), generato da
-- scripts/generate-content-seed.ts a partire da content/lessons/.
-- NON modificare a mano: rigenera con `npm run generate-content-seed`.
-- Idempotente: upsert su `id`; gli id derivano dal contenuto
-- (lessonId/deriveExerciseId), quindi un contenuto invariato non cambia nulla.

insert into lesson (id, ordinal, title_en, title_it, grammar_points) values
  ('が-が示す主語', 1, 'The subject with が, and the three predicates', 'Il soggetto con が, e i tre predicati', array['「が」が示す主語', '述語の三つの形']),
  ('ゼロ代名詞', 2, 'The zero pronoun, and the object with を', 'Il pronome zero, e l''oggetto con を', array['ゼロ代名詞', '「を」で示す目的語']),
  ('は-が示す主題', 3, 'The topic with は, and the target with に', 'Il tema con は, e il destinatario con に', array['「は」が示す主題', '到達点を示す「に」']),
  ('非過去形', 4, 'Non-past, ongoing and past; time words with or without に', 'Non passato, in corso e passato; le espressioni di tempo con o senza に', array['非過去形', '「ている」の進行', '過去形の「た」', '時を示す「に」']),
  ('動詞の三つのグループ', 5, 'The three verb groups and the te/ta forms', 'I tre gruppi verbali e le forme in て/た', array['動詞の三つのグループ', 'て形・た形の作り方']),
  ('名詞を修飾する述語', 6, 'Describing a noun: predicates, な and の', 'Descrivere un nome: predicati, な e の', array['名詞を修飾する述語', '名詞を修飾する「な」', '名詞を修飾する「の」']),
  ('否定の-ない', 7, 'Negation with ない', 'La negazione con ない', array['否定の「ない」', '名詞文の否定「ではない」', '形容詞の否定「くない」', '丁寧な否定「ません」']),
  ('動詞の語幹と助動詞', 8, 'Verb stems and the auxiliaries that attach to them', 'I radicali del verbo e gli ausiliari che vi si attaccano', array['動詞の語幹と助動詞', '連用形につく「ます」「たい」', '未然形につく「せる」「れる」', '意向形']),
  ('目的地を示す-に', 9, 'The particle に: destination, purpose, location, change; and へ', 'La particella に: destinazione, scopo, luogo, cambiamento; e へ', array['目的地を示す「に」', '目的を示す「に」', '存在の場所を示す「に」', '変化の結果を示す「に」', '方向を示す「へ」']),
  ('動作の場所を示す-で', 10, 'で for the place of an action and for the means; と to join nouns', 'で per il luogo di un''azione e per il mezzo; と per unire i nomi', array['動作の場所を示す「で」', '手段を示す「で」', '名詞をつなぐ「と」']),
  ('感情-理解の述語と-が', 11, 'が with 好き, 分かる, ほしい and たい; がる for other people', 'が con 好き, 分かる, ほしい e たい; がる per gli altri', array['感情・理解の述語と「が」', '欲求の「ほしい」と「たい」', '他人の感情を示す「がる」']),
  ('可能形', 12, 'The potential form and できる', 'La forma potenziale e できる', array['可能形', '不規則動詞の可能形', '可能形と「が」']),
  ('て形で節をつなぐ', 13, 'Joining clauses with the te-form; てくれる and てあげる', 'Unire proposizioni con la forma in て; てくれる e てあげる', array['て形で節をつなぐ', '恩恵を受ける「てくれる」', '恩恵を与える「てあげる」'])
on conflict (id) do update set
  ordinal = excluded.ordinal,
  title_en = excluded.title_en,
  title_it = excluded.title_it,
  grammar_points = excluded.grammar_points;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('57975a13-e0c2-5eda-9d3f-5bb832248016', 'が-が示す主語', 'assemble', '{"sentence":{"kanji":"妹が毎朝歌います","kana":"いもうとがまいあさうたいます"},"answer":["妹が","毎朝","歌います"],"prompt":{"en":"Build: \"My younger sister sings every morning.\"","it":"Componi: «Mia sorella minore canta ogni mattina.»"}}'::jsonb, '「が」が示す主語', 'が marks the subject: it tells you which element the predicate is about. Here 妹 (younger sister) is the subject and 歌います (sings) is the predicate. 毎朝 (every morning) adds information but is not the subject, so it carries no が. A sentence has exactly one subject marked by が.', 'が marca il soggetto: dice di quale elemento parla il predicato. Qui 妹 (sorella minore) è il soggetto e 歌います (canta) è il predicato. 毎朝 (ogni mattina) aggiunge informazione ma non è il soggetto, quindi non porta が. Una frase ha esattamente un soggetto marcato da が.'),
  ('2e47b85b-29ba-54d7-a09a-2533decd1cb3', 'が-が示す主語', 'select-span', '{"sentence":{"kanji":"妹が学生だ","kana":"いもうとががくせいだ"},"answer":{"start":1,"end":2},"prompt":{"en":"Which part is the copula?","it":"Quale parte è la copula?"}}'::jsonb, '述語の三つの形', 'Select the copula. だ states an identity between the subject and what precedes it: 妹 = 学生. The relation holds in one direction only — this sentence says the sister is a student, not that students are the sister. だ is one of the three things a predicate can end with; the other two are a verb and an い-adjective.', 'Seleziona la copula. だ afferma un''identità fra il soggetto e ciò che la precede: 妹 = 学生. La relazione vale in una sola direzione — questa frase dice che la sorella è una studentessa, non che le studentesse siano la sorella. だ è una delle tre cose con cui un predicato può chiudersi; le altre due sono un verbo e un aggettivo in い.'),
  ('8347f682-389b-5c65-81af-6af0f0424823', 'が-が示す主語', 'single-select', '{"sentence":{"kanji":"水が冷たい","kana":"みずがつめたい"},"answer":"冷たい","distractors":["冷たいだ","冷だ","冷たくだ"],"gap":{"kanji":"水が＿","kana":"みずが＿"},"prompt":{"en":"\"The water is cold.\" Which predicate is correct?","it":"«L''acqua è fredda.» Qual è il predicato corretto?"}}'::jsonb, '述語の三つの形', 'An い-adjective is already a complete predicate: 冷たい does not mean "cold", it means "is cold". The identity function that だ performs is built into the adjective, so だ is never added after an い-adjective. This is why a predicate can end in three ways — a verb, だ, or an い-adjective — and never in two of them at once.', 'Un aggettivo in い è già un predicato completo: 冷たい non significa «freddo», significa «è freddo». La funzione di identità che svolge だ è incorporata nell''aggettivo, quindi だ non si aggiunge mai dopo un aggettivo in い. È la ragione per cui un predicato può chiudersi in tre modi — un verbo, だ, o un aggettivo in い — e mai in due insieme.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('0f32d14b-3435-526b-bbac-b35ac5c7db99', 'ゼロ代名詞', 'assemble', '{"sentence":{"kanji":"弟がパンを焼く","kana":"おとうとがパンをやく"},"answer":["弟が","パンを","焼く"],"prompt":{"en":"Build: \"My younger brother bakes bread.\"","it":"Componi: «Mio fratello minore cuoce il pane.»"}}'::jsonb, '「を」で示す目的語', 'Two roles, two particles. が marks 弟 (younger brother) as the one who performs the action; を marks パン (bread) as what the action is applied to — the object. Each particle travels with its noun, and the verb 焼く (bake) closes the sentence.', 'Due ruoli, due particelle. が marca 弟 (fratello minore) come chi compie l''azione; を marca パン (pane) come ciò su cui l''azione si esercita — l''oggetto. Ogni particella viaggia con il suo nome, e il verbo 焼く (cuocere) chiude la frase.'),
  ('3ac7b3aa-91eb-55f4-bd8b-99d8c49f8990', 'ゼロ代名詞', 'select-span', '{"sentence":{"kanji":"ピザを焼いた","kana":"ピザをやいた"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part is the object of the verb?","it":"Quale parte è l''oggetto del verbo?"}}'::jsonb, '「を」で示す目的語', 'Select the object: ピザを. を marks the pizza as the thing that was baked. No subject is written, yet the sentence is complete: its subject is a zero pronoun, understood as the speaker unless the context points to someone else — "I baked a pizza".', 'Seleziona l''oggetto: ピザを. を marca la pizza come la cosa che è stata cotta. Nessun soggetto è scritto, eppure la frase è completa: il suo soggetto è un pronome zero, inteso come chi parla a meno che il contesto indichi qualcun altro — «ho cotto una pizza».'),
  ('aa3360be-653c-52cd-bcc5-aacdbd09a332', 'ゼロ代名詞', 'single-select', '{"sentence":{"kanji":"猫が魚を食べた","kana":"ねこがさかなをたべた"},"answer":"を","distractors":["が","の"],"gap":{"kanji":"猫が魚＿食べた","kana":"ねこがさかな＿たべた"},"prompt":{"en":"\"The cat ate the fish.\" Which particle marks what was eaten?","it":"«Il gatto ha mangiato il pesce.» Quale particella marca ciò che è stato mangiato?"}}'::jsonb, '「を」で示す目的語', 'The fish is what gets eaten, so it takes the object particle を. が is already used by 猫 (cat), the one who eats; の would turn 魚 into a modifier of the next noun, but a verb follows, not a noun.', 'Il pesce è ciò che viene mangiato, quindi prende la particella dell''oggetto を. が è già usata da 猫 (gatto), chi mangia; の farebbe di 魚 un modificatore del nome seguente, ma segue un verbo, non un nome.'),
  ('0cde5b10-898c-581d-9750-a83dbf5ad084', 'ゼロ代名詞', 'select-span', '{"sentence":{"kanji":"もう八時だ","kana":"もうはちじだ"},"answer":{"start":2,"end":3},"prompt":{"en":"No subject is written. Which part is the copula?","it":"Il soggetto non è scritto. Quale parte è la copula?"}}'::jsonb, 'ゼロ代名詞', 'Select the copula だ. The sentence has a predicate (八時だ, "is eight o''clock") but no written subject. Japanese does not need one on the page: the subject is a zero pronoun whose value comes from the situation — here, the present time.', 'Seleziona la copula だ. La frase ha un predicato (八時だ, «sono le otto») ma nessun soggetto scritto. Il giapponese non ha bisogno di scriverlo: il soggetto è un pronome zero il cui valore viene dalla situazione — qui, l''ora attuale.'),
  ('e9ac22ea-8073-5d03-a921-43dbccd1614e', 'ゼロ代名詞', 'assemble', '{"sentence":{"kanji":"毎晩日記を書く","kana":"まいばんにっきをかく"},"answer":["毎晩","日記を","書く"],"prompt":{"en":"Build: \"(I) write in my diary every night.\"","it":"Componi: «(Io) scrivo il diario ogni sera.»"}}'::jsonb, 'ゼロ代名詞', 'There is no が anywhere, but every action still has someone performing it. The subject of 書く (write) is a zero pronoun; with nothing else in the context, it defaults to the speaker: "I write in my diary every night".', 'Non c''è nessun が, ma ogni azione ha comunque qualcuno che la compie. Il soggetto di 書く (scrivere) è un pronome zero; se il contesto non dice altro, vale chi parla: «ogni sera scrivo il diario».'),
  ('579c5b10-3119-59bc-8ed4-87dd1c948f35', 'ゼロ代名詞', 'single-select', '{"sentence":{"kanji":"窓を開ける","kana":"まどをあける"},"answer":"を","distractors":["が","で"],"gap":{"kanji":"窓＿開ける","kana":"まど＿あける"},"prompt":{"en":"\"(I) open the window.\" Which particle marks the window?","it":"«(Io) apro la finestra.» Quale particella marca la finestra?"}}'::jsonb, 'ゼロ代名詞', '窓 (window) is what gets opened, so it is the object and takes を. With が the window would become the subject, and the sentence would lose the person who opens it. That person is still there as a zero pronoun: "(I) open the window".', '窓 (finestra) è ciò che viene aperto, quindi è l''oggetto e prende を. Con が la finestra diventerebbe il soggetto, e la frase perderebbe chi la apre. Quella persona c''è comunque, come pronome zero: «(io) apro la finestra».')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('18239c82-53c0-5b50-b5ea-1ea27f2ef47b', 'は-が示す主題', 'select-span', '{"sentence":{"kanji":"これは私の傘だ","kana":"これはわたしのかさだ"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part is the topic?","it":"Quale parte è il tema?"}}'::jsonb, '「は」が示す主題', 'Select the topic: これは. は announces what the sentence is about — "as for this" — and then steps aside. It is not a case particle: it gives the noun no grammatical role (subject, object, target): the subject of 私の傘だ is left unspoken and is understood from the topic.', 'Seleziona il tema: これは. は annuncia di che cosa parla la frase — «quanto a questo» — e poi si fa da parte. Non è una particella di caso: non assegna al nome alcun ruolo grammaticale (soggetto, oggetto, destinatario): il soggetto di 私の傘だ resta sottinteso e si ricava dal tema.'),
  ('4a486ed2-e831-53d7-bb03-619e7e55f5e5', 'は-が示す主題', 'single-select', '{"sentence":{"kanji":"東京は人が多い","kana":"とうきょうはひとがおおい"},"answer":"は","distractors":["を","へ"],"gap":{"kanji":"東京＿人が多い","kana":"とうきょう＿ひとがおおい"},"prompt":{"en":"\"As for Tokyo, there are many people.\" Which particle marks Tokyo?","it":"«Quanto a Tokyo, ci sono molte persone.» Quale particella marca Tokyo?"}}'::jsonb, '「は」が示す主題', 'The subject of 多い (are many) is 人, already marked by が. 東京 has no grammatical role in the predicate: it only sets the scene, "as for Tokyo". Marking what the sentence is about, without a grammatical role, is exactly the job of は.', 'Il soggetto di 多い (sono molti) è 人, già marcato da が. 東京 non ha alcun ruolo grammaticale nel predicato: fissa solo la scena, «quanto a Tokyo». Marcare ciò di cui si parla, senza un ruolo grammaticale, è esattamente il compito di は.'),
  ('8bd02c8c-712f-5b02-950e-c60858e8f452', 'は-が示す主題', 'assemble', '{"sentence":{"kanji":"私は毎日コーヒーを飲む","kana":"わたしはまいにちコーヒーをのむ"},"answer":["私は","毎日","コーヒーを","飲む"],"prompt":{"en":"Build: \"I drink coffee every day.\" Start with the topic.","it":"Componi: «Bevo caffè ogni giorno.» Comincia dal tema."}}'::jsonb, '「は」が示す主題', '私は is the topic: "as for me". The one who drinks is an unspoken subject that the topic makes clear. Moving は onto another noun would change the emphasis — what the sentence is about — but never who does what; that is fixed by the case particles such as が and を.', '私は è il tema: «quanto a me». Chi beve è un soggetto sottinteso che il tema rende chiaro. Spostare は su un altro nome cambierebbe l''enfasi — ciò di cui si parla — ma mai chi fa cosa: quello lo fissano le particelle di caso come が e を.'),
  ('61e926e3-590c-5339-9425-120cfbbb25da', 'は-が示す主題', 'select-span', '{"sentence":{"kanji":"ポストに手紙を入れた","kana":"ポストにてがみをいれた"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part says where the letter ends up?","it":"Quale parte dice dove finisce la lettera?"}}'::jsonb, '到達点を示す「に」', 'Select the target of the action: ポストに. The letter is the object (を); the postbox is where the action ends up, so it is marked by に. The one who put the letter in is an unspoken subject.', 'Seleziona il punto d''arrivo dell''azione: ポストに. La lettera è l''oggetto (を); la cassetta postale è dove l''azione va a finire, quindi è marcata da に. Chi ha imbucato la lettera è un soggetto sottinteso.'),
  ('f1d776a4-259a-5651-914b-90de125c1c1c', 'は-が示す主題', 'single-select', '{"sentence":{"kanji":"先生に花をあげた","kana":"せんせいにはなをあげた"},"answer":"に","distractors":["を","で"],"gap":{"kanji":"先生＿花をあげた","kana":"せんせい＿はなをあげた"},"prompt":{"en":"\"I gave flowers to the teacher.\" Which particle marks the recipient?","it":"«Ho dato dei fiori all''insegnante.» Quale particella marca il destinatario?"}}'::jsonb, '到達点を示す「に」', '花 (flowers) is what is given, so it takes を. The teacher is the recipient — the person the giving is aimed at — and a recipient is marked by に.', '花 (fiori) è ciò che viene dato, quindi prende を. L''insegnante è il destinatario — la persona a cui il dare è rivolto — e un destinatario è marcato da に.'),
  ('34bfcd4c-14f4-5e5a-86c3-764f90e7c57a', 'は-が示す主題', 'assemble', '{"sentence":{"kanji":"姉が友達に手紙を送った","kana":"あねがともだちにてがみをおくった"},"answer":["姉が","友達に","手紙を","送った"],"prompt":{"en":"Build: \"My older sister sent a letter to a friend.\"","it":"Componi: «Mia sorella maggiore ha spedito una lettera a un amico.»"}}'::jsonb, '到達点を示す「に」', 'が marks who sends (姉, older sister), に marks who the letter goes to (友達, a friend), を marks what is sent (手紙, a letter). The particles, not the word order, decide the roles: this is the most neutral order, but 手紙を could also come before 友達に without changing the meaning.', 'が marca chi spedisce (姉, sorella maggiore), に marca a chi va la lettera (友達, un amico), を marca ciò che viene spedito (手紙, una lettera). Sono le particelle, non l''ordine delle parole, a decidere i ruoli: questo è l''ordine più neutro, ma 手紙を potrebbe venire prima di 友達に senza cambiare il significato.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('b7d38cc8-562b-59dd-92df-b6599109a919', '非過去形', 'single-select', '{"sentence":{"kanji":"明日は雨が降る","kana":"あしたはあめがふる"},"answer":"降る","distractors":["降った","降っていた"],"gap":{"kanji":"明日は雨が＿","kana":"あしたはあめが＿"},"prompt":{"en":"\"It will rain tomorrow.\" Which verb form fits?","it":"«Domani pioverà.» Quale forma del verbo è giusta?"}}'::jsonb, '非過去形', 'The dictionary form is a non-past tense, not a present: most of the time it describes something that will happen. With 明日 (tomorrow), 降る means "it will rain". A past form cannot go with tomorrow.', 'La forma del dizionario è un tempo non passato, non un presente: il più delle volte descrive qualcosa che accadrà. Con 明日 (domani), 降る significa «pioverà». Una forma al passato non può stare con domani.'),
  ('3ed770d8-53e8-583b-9402-cdba8605fcb4', '非過去形', 'single-select', '{"sentence":{"kanji":"父が新聞を読んでいる","kana":"ちちがしんぶんをよんでいる"},"answer":"読んでいる","distractors":["読むいる","読みている","読んいる"],"gap":{"kanji":"父が新聞を＿","kana":"ちちがしんぶんを＿"},"prompt":{"en":"\"My father is reading the newspaper.\" Which form says the action is in progress?","it":"«Mio padre sta leggendo il giornale.» Quale forma dice che l''azione è in corso?"}}'::jsonb, '「ている」の進行', 'An action in progress is the te-form of the verb followed by いる: "is reading". 読む ends in む, so its te-form is 読んで; いる cannot attach to the dictionary form or to the stem.', 'Un''azione in corso è la forma in て del verbo seguita da いる: «sta leggendo». 読む finisce in む, quindi la sua forma in て è 読んで; いる non si attacca alla forma del dizionario né al radicale.'),
  ('3b4b6752-0757-51a1-b94d-13f807ec11e8', '非過去形', 'select-span', '{"sentence":{"kanji":"妹がテレビを見ている","kana":"いもうとがテレビをみている"},"answer":{"start":1,"end":2},"prompt":{"en":"Which part shows that the action is in progress?","it":"Quale parte indica che l''azione è in corso?"}}'::jsonb, '「ている」の進行', 'Select ている. 見る (watch) is a verb that drops る before an ending, so its te-form is 見て; adding いる gives "is watching". The sentence describes what is happening right now.', 'Seleziona ている. 見る (guardare) è un verbo che perde る davanti a una desinenza, quindi la sua forma in て è 見て; aggiungendo いる si ottiene «sta guardando». La frase descrive ciò che accade in questo momento.'),
  ('2281b09b-cfa1-5201-b30a-a4d0e9916bdd', '非過去形', 'select-span', '{"sentence":{"kanji":"昨日カレーを作った","kana":"きのうカレーをつくった"},"answer":{"start":1,"end":2},"prompt":{"en":"Which part carries the past tense?","it":"Quale parte porta il passato?"}}'::jsonb, '過去形の「た」', 'Select the part that carries the past: った. The past tense is formed exactly like the te-form, with た in place of て: 作る → 作って → 作った. 昨日 (yesterday) is relative to today, so it needs no particle.', 'Seleziona la parte che porta il passato: った. Il passato si forma esattamente come la forma in て, con た al posto di て: 作る → 作って → 作った. 昨日 (ieri) è relativo a oggi, quindi non richiede particella.'),
  ('5f4f76f1-97eb-5e69-b160-43aaeca96e13', '非過去形', 'assemble', '{"sentence":{"kanji":"先週新しい靴を買った","kana":"せんしゅうあたらしいくつをかった"},"answer":["先週","新しい","靴を","買った"],"prompt":{"en":"Build: \"I bought new shoes last week.\"","it":"Componi: «La settimana scorsa ho comprato delle scarpe nuove.»"}}'::jsonb, '過去形の「た」', '先週 (last week) is measured from now, so it stands at the front with no particle and places the whole sentence in that time. 買う ends in う, so its past is 買った.', '先週 (la settimana scorsa) si misura a partire da adesso, quindi sta in testa senza particella e colloca tutta la frase in quel tempo. 買う finisce in う, quindi il suo passato è 買った.'),
  ('4af79a02-6a52-5ed0-8de8-d892d154cd92', '非過去形', 'assemble', '{"sentence":{"kanji":"七時に友達が来る","kana":"しちじにともだちがくる"},"answer":["七時に","友達が","来る"],"prompt":{"en":"Build: \"A friend is coming at seven.\"","it":"Componi: «Alle sette viene un amico.»"}}'::jsonb, '時を示す「に」', '七時 (seven o''clock) is a fixed point on the clock, not a time measured from today, so it takes に. A quick test: if English needs "at", "on" or "in" before the time word, Japanese needs に. The non-past 来る refers to a future arrival.', '七時 (le sette) è un punto fisso dell''orologio, non un tempo misurato da oggi, quindi prende に. Una prova rapida: se in inglese serve «at», «on» o «in» davanti all''espressione di tempo, in giapponese serve に. Il non passato 来る indica un arrivo futuro.'),
  ('1362ab6a-c76c-52f2-8990-3d5c04dced59', '非過去形', 'single-select', '{"sentence":{"kanji":"来年大学を卒業する","kana":"らいねんだいがくをそつぎょうする"},"answer":"来年","distractors":["来年を","来年が"],"gap":{"kanji":"＿大学を卒業する","kana":"＿だいがくをそつぎょうする"},"prompt":{"en":"\"I will graduate from university next year.\" How is \"next year\" written here?","it":"«L''anno prossimo mi laureo.» Come si scrive qui «l''anno prossimo»?"}}'::jsonb, '時を示す「に」', '来年 (next year) only makes sense relative to the present year, so it takes no particle: it simply opens the sentence. に is for absolute times such as a date, a weekday or an hour; を and が would turn 来年 into an object or a subject, which it is not.', '来年 (l''anno prossimo) ha senso solo rispetto all''anno in corso, quindi non prende particella: apre semplicemente la frase. に serve per i tempi assoluti, come una data, un giorno della settimana o un''ora; を e が farebbero di 来年 un oggetto o un soggetto, e non lo è.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('3edb0ae6-beb3-5405-a88e-42582289500c', '動詞の三つのグループ', 'single-select', '{"sentence":{"kanji":"朝ごはんを食べた","kana":"あさごはんをたべた"},"answer":"食べた","distractors":["食べった","食べいた","食んだ"],"gap":{"kanji":"朝ごはんを＿","kana":"あさごはんを＿"},"prompt":{"en":"\"I ate breakfast.\" What is the past of 食べる?","it":"«Ho fatto colazione.» Qual è il passato di 食べる?"}}'::jsonb, '動詞の三つのグループ', '食べる is an ichidan verb (it ends in -eru and belongs to the simplest group): to attach anything, you remove る and add the ending. So the past is 食べ + た.', '食べる è un verbo ichidan (finisce in -eru e appartiene al gruppo più semplice): per attaccare qualunque cosa si toglie る e si aggiunge la desinenza. Quindi il passato è 食べ + た.'),
  ('d5c8da5e-6e1b-5e48-b374-a114cb6e4e43', '動詞の三つのグループ', 'single-select', '{"sentence":{"kanji":"毎朝公園を走っている","kana":"まいあさこうえんをはしっている"},"answer":"走って","distractors":["走て","走りて","走んで"],"gap":{"kanji":"毎朝公園を＿いる","kana":"まいあさこうえんを＿いる"},"prompt":{"en":"\"I run in the park every morning.\" What is the te-form of 走る?","it":"«Ogni mattina corro al parco.» Qual è la forma in て di 走る?"}}'::jsonb, '動詞の三つのグループ', '走る ends in -iru but is a godan verb, one of the minority that look like ichidan verbs. Godan verbs in る form the te-form with a small っ: 走る → 走って. Treating it as ichidan would give the wrong 走て.', '走る finisce in -iru ma è un verbo godan, uno della minoranza che somiglia agli ichidan. I verbi godan in る formano la forma in て con una piccola っ: 走る → 走って. Trattarlo come ichidan darebbe l''errato 走て.'),
  ('cd298cc6-62a9-54aa-8f73-d88e3c6214f9', '動詞の三つのグループ', 'single-select', '{"sentence":{"kanji":"弟が薬を飲んだ","kana":"おとうとがくすりをのんだ"},"answer":"飲んだ","distractors":["飲った","飲いだ","飲みた"],"gap":{"kanji":"弟が薬を＿","kana":"おとうとがくすりを＿"},"prompt":{"en":"\"My younger brother took the medicine.\" What is the past of 飲む?","it":"«Mio fratello minore ha preso la medicina.» Qual è il passato di 飲む?"}}'::jsonb, 'て形・た形の作り方', 'Godan verbs ending in む, ぶ or ぬ replace that syllable with ん and a voiced ending: んで for the te-form, んだ for the past. So 飲む (drink) → 飲んだ.', 'I verbi godan in む, ぶ o ぬ sostituiscono quella sillaba con ん e una desinenza sonora: んで per la forma in て, んだ per il passato. Quindi 飲む (bere) → 飲んだ.'),
  ('a83154b8-bddd-5726-ad4a-9cc36ddc9b02', '動詞の三つのグループ', 'single-select', '{"sentence":{"kanji":"昨日プールで泳いだ","kana":"きのうプールでおよいだ"},"answer":"泳いだ","distractors":["泳った","泳んだ","泳いた"],"gap":{"kanji":"昨日プールで＿","kana":"きのうプールで＿"},"prompt":{"en":"\"I swam in the pool yesterday.\" What is the past of 泳ぐ?","it":"«Ieri ho nuotato in piscina.» Qual è il passato di 泳ぐ?"}}'::jsonb, 'て形・た形の作り方', 'Verbs in く become いて/いた; verbs in ぐ follow the same pattern with voicing, いで/いだ. 泳ぐ (swim) ends in ぐ, so its past is 泳いだ, not 泳いた.', 'I verbi in く diventano いて/いた; i verbi in ぐ seguono lo stesso schema con la sonorizzazione, いで/いだ. 泳ぐ (nuotare) finisce in ぐ, quindi il passato è 泳いだ, non 泳いた.'),
  ('5a77229e-6cec-5a7a-a56d-015085d4fd93', '動詞の三つのグループ', 'select-span', '{"sentence":{"kanji":"手紙を出した","kana":"てがみをだした"},"answer":{"start":1,"end":2},"prompt":{"en":"Which part is the past ending of 出す?","it":"Quale parte è la desinenza del passato di 出す?"}}'::jsonb, 'て形・た形の作り方', 'Select した. Verbs ending in す change it to し before て or た: 出す (send) → 出して → 出した. It is the same shift from the u-row to the i-row that other endings use.', 'Seleziona した. I verbi in す la cambiano in し davanti a て o た: 出す (spedire) → 出して → 出した. È lo stesso passaggio dalla riga in u alla riga in i che usano altre desinenze.'),
  ('10054a46-427c-5262-9c64-6c52b362676c', '動詞の三つのグループ', 'assemble', '{"sentence":{"kanji":"歩いて学校に行った","kana":"あるいてがっこうにいった"},"answer":["歩いて","学校に","行った"],"prompt":{"en":"Build: \"I walked to school.\"","it":"Componi: «Sono andato a scuola a piedi.»"}}'::jsonb, 'て形・た形の作り方', '歩く (walk) follows the く rule: 歩いて. 行く (go) is the one exception to that rule: it becomes 行って/行った, never 行いた.', '歩く (camminare) segue la regola dei verbi in く: 歩いて. 行く (andare) è l''unica eccezione a quella regola: diventa 行って/行った, mai 行いた.'),
  ('3b9faea7-4987-5660-b634-29e62290f61d', '動詞の三つのグループ', 'single-select', '{"sentence":{"kanji":"日曜日に友達が来た","kana":"にちようびにともだちがきた"},"answer":"来た","distractors":["来った","来いた","来んだ"],"gap":{"kanji":"日曜日に友達が＿","kana":"にちようびにともだちが＿"},"prompt":{"en":"\"A friend came on Sunday.\" What is the past of 来る?","it":"«Domenica è venuto un amico.» Qual è il passato di 来る?"}}'::jsonb, '動詞の三つのグループ', 'Japanese has only two irregular verbs: 来る (come) and する (do). Their te/ta forms must be learned as they are: 来る → 来て/来た (read きて/きた), する → して/した.', 'Il giapponese ha solo due verbi irregolari: 来る (venire) e する (fare). Le loro forme in て/た vanno imparate così come sono: 来る → 来て/来た (letti きて/きた), する → して/した.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('88bacd49-0013-53ad-8822-bc64198450cd', '名詞を修飾する述語', 'select-span', '{"sentence":{"kanji":"おいしい店に行った","kana":"おいしいみせにいった"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part describes the shop?","it":"Quale parte descrive il locale?"}}'::jsonb, '名詞を修飾する述語', 'Select the word that describes 店 (shop): おいしい. An い-adjective is a complete predicate on its own; placed directly before a noun, it describes that noun — "a shop that is delicious", a good place to eat.', 'Seleziona la parola che descrive 店 (locale): おいしい. Un aggettivo in い è da solo un predicato completo; messo subito prima di un nome, descrive quel nome — «un locale che è buono», un posto dove si mangia bene.'),
  ('f514db52-f4fc-5d2f-af57-5ff12b9949c1', '名詞を修飾する述語', 'assemble', '{"sentence":{"kanji":"昨日買った傘が壊れた","kana":"きのうかったかさがこわれた"},"answer":["昨日","買った","傘が","壊れた"],"prompt":{"en":"Build: \"The umbrella I bought yesterday broke.\"","it":"Componi: «L''ombrello che ho comprato ieri si è rotto.»"}}'::jsonb, '名詞を修飾する述語', 'A whole verb clause can describe a noun, just by standing in front of it. 昨日買った (bought yesterday) describes 傘 (umbrella): "the umbrella I bought yesterday broke". Japanese has no word for "that" or "which": position alone does the work.', 'Un''intera proposizione verbale può descrivere un nome, semplicemente mettendosi davanti a esso. 昨日買った (comprato ieri) descrive 傘 (ombrello): «l''ombrello che ho comprato ieri si è rotto». Il giapponese non ha una parola per «che»: basta la posizione.'),
  ('349ef8de-fce0-5138-84a5-10426df29fe8', '名詞を修飾する述語', 'single-select', '{"sentence":{"kanji":"静かな町に住んでいる","kana":"しずかなまちにすんでいる"},"answer":"静かな","distractors":["静かだ","静かの","静かい"],"gap":{"kanji":"＿町に住んでいる","kana":"＿まちにすんでいる"},"prompt":{"en":"\"I live in a quiet town.\" Which form of 静か goes before a noun?","it":"«Vivo in una città tranquilla.» Quale forma di 静か va davanti a un nome?"}}'::jsonb, '名詞を修飾する「な」', '静か (quiet) is a noun of the adjectival kind, the so-called な-adjective. At the end of a sentence it takes だ (町が静かだ); when it sits before a noun to describe it, だ becomes な: 静かな町.', '静か (tranquillo) è un nome di tipo aggettivale, il cosiddetto aggettivo in な. A fine frase prende だ (町が静かだ); quando sta davanti a un nome per descriverlo, だ diventa な: 静かな町.'),
  ('dfcc733a-c32e-5f45-9fd1-43b4c27d2055', '名詞を修飾する述語', 'assemble', '{"sentence":{"kanji":"有名な歌手が来た","kana":"ゆうめいなかしゅがきた"},"answer":["有名な","歌手が","来た"],"prompt":{"en":"Build: \"A famous singer came.\"","it":"Componi: «È venuto un cantante famoso.»"}}'::jsonb, '名詞を修飾する「な」', '有名 (famous) is a な-adjective: before the noun 歌手 (singer) it takes な. The phrase 有名な歌手 as a whole is then marked by が as the subject of 来た (came).', '有名 (famoso) è un aggettivo in な: davanti al nome 歌手 (cantante) prende な. L''intera espressione 有名な歌手 è poi marcata da が come soggetto di 来た (è venuto).'),
  ('79ae205c-615d-5647-9b01-d6800dee970c', '名詞を修飾する述語', 'single-select', '{"sentence":{"kanji":"木の机を買った","kana":"きのつくえをかった"},"answer":"の","distractors":["な","が"],"gap":{"kanji":"木＿机を買った","kana":"き＿つくえをかった"},"prompt":{"en":"\"I bought a wooden desk.\" Which particle links 木 to 机?","it":"«Ho comprato una scrivania di legno.» Quale particella collega 木 a 机?"}}'::jsonb, '名詞を修飾する「の」', '木 (wood) is an ordinary noun, not a な-adjective, so it cannot take な. To let one noun describe another — its owner, its material, the kind it belongs to — Japanese uses の: 木の机, a wooden desk.', '木 (legno) è un nome ordinario, non un aggettivo in な, quindi non può prendere な. Per far descrivere un nome da un altro — il possessore, il materiale, il tipo a cui appartiene — il giapponese usa の: 木の机, una scrivania di legno.'),
  ('3be87963-5201-5b19-a2c5-b8b43bc26ea1', '名詞を修飾する述語', 'single-select', '{"sentence":{"kanji":"日本語の先生が来た","kana":"にほんごのせんせいがきた"},"answer":"の","distractors":["な","だ"],"gap":{"kanji":"日本語＿先生が来た","kana":"にほんご＿せんせいがきた"},"prompt":{"en":"\"The Japanese teacher came.\" Which particle links the two nouns?","it":"«È venuto l''insegnante di giapponese.» Quale particella collega i due nomi?"}}'::jsonb, '名詞を修飾する「の」', '日本語の先生 is "a teacher of Japanese": の links the noun 日本語 to the noun 先生 and tells what kind of teacher it is. だ closes a sentence and cannot join two nouns; な belongs to the adjectival nouns only.', '日本語の先生 è «un insegnante di giapponese»: の collega il nome 日本語 al nome 先生 e dice di che tipo di insegnante si tratta. だ chiude una frase e non può unire due nomi; な appartiene solo ai nomi aggettivali.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('de4b81da-1d12-5346-860e-ea0c1cad7e66', '否定の-ない', 'single-select', '{"sentence":{"kanji":"今日は時間がない","kana":"きょうはじかんがない"},"answer":"ない","distractors":["あらない","ないだ","なく"],"gap":{"kanji":"今日は時間が＿","kana":"きょうはじかんが＿"},"prompt":{"en":"\"I have no time today.\" What is the negative of ある?","it":"«Oggi non ho tempo.» Qual è la negazione di ある?"}}'::jsonb, '否定の「ない」', 'ある (there is) has no regular negative: "there is not" is the い-adjective ない. Because ない is an adjective, it is already a full predicate and never takes だ.', 'ある (c''è) non ha una negazione regolare: «non c''è» è l''aggettivo in い ない. Poiché ない è un aggettivo, è già un predicato completo e non prende mai だ.'),
  ('b377835e-ce27-5345-8523-26d307f4fa86', '否定の-ない', 'single-select', '{"sentence":{"kanji":"兄はお酒を飲まない","kana":"あにはおさけをのまない"},"answer":"飲まない","distractors":["飲むない","飲みない","飲まらない"],"gap":{"kanji":"兄はお酒を＿","kana":"あにはおさけを＿"},"prompt":{"en":"\"My older brother doesn''t drink alcohol.\" What is the negative of 飲む?","it":"«Mio fratello maggiore non beve alcolici.» Qual è la negazione di 飲む?"}}'::jsonb, '否定の「ない」', 'A verb is made negative by attaching ない to its a-stem: the final u-row kana moves to the a-row. 飲む → 飲ま + ない. The result is an い-adjective, so the negative verb behaves like one.', 'Un verbo si nega attaccando ない al suo radicale in a: l''ultimo kana della riga in u passa alla riga in a. 飲む → 飲ま + ない. Il risultato è un aggettivo in い, quindi il verbo negato si comporta come tale.'),
  ('42743f63-d12a-5fe3-845f-62a6c9511434', '否定の-ない', 'single-select', '{"sentence":{"kanji":"母は肉を買わない","kana":"はははにくをかわない"},"answer":"買わない","distractors":["買あない","買いない","買うない"],"gap":{"kanji":"母は肉を＿","kana":"はははにくを＿"},"prompt":{"en":"\"My mother doesn''t buy meat.\" What is the negative of 買う?","it":"«Mia madre non compra carne.» Qual è la negazione di 買う?"}}'::jsonb, '否定の「ない」', 'The only irregularity of the a-stem: verbs ending in う take わ instead of あ. So 買う (buy) → 買わない, not 買あない.', 'L''unica irregolarità del radicale in a: i verbi in う prendono わ invece di あ. Quindi 買う (comprare) → 買わない, non 買あない.'),
  ('15e5d9ee-259e-58fd-952b-2a29db6134f7', '否定の-ない', 'select-span', '{"sentence":{"kanji":"あれは駅ではない","kana":"あれはえきではない"},"answer":{"start":2,"end":3},"prompt":{"en":"Which part makes the sentence negative?","it":"Quale parte rende negativa la frase?"}}'::jsonb, '名詞文の否定「ではない」', 'Select the negative ending: ではない. A noun sentence is negated by turning だ into its te-form で, adding は, and then ない: 駅だ → 駅ではない, "is not a station". In speech it often contracts to じゃない.', 'Seleziona la desinenza negativa: ではない. Una frase nominale si nega trasformando だ nella sua forma in て で, aggiungendo は e poi ない: 駅だ → 駅ではない, «non è una stazione». Nel parlato si contrae spesso in じゃない.'),
  ('ef8c40a5-800f-5e9f-a558-497b7536040a', '否定の-ない', 'single-select', '{"sentence":{"kanji":"この部屋は寒くない","kana":"このへやはさむくない"},"answer":"寒くない","distractors":["寒いない","寒いではない","寒じゃない"],"gap":{"kanji":"この部屋は＿","kana":"このへやは＿"},"prompt":{"en":"\"This room is not cold.\" What is the negative of 寒い?","it":"«Questa stanza non è fredda.» Qual è la negazione di 寒い?"}}'::jsonb, '形容詞の否定「くない」', 'An い-adjective changes its final い into く before any addition: 寒い (cold) → 寒く + ない. ではない is only for nouns and な-adjectives.', 'Un aggettivo in い cambia la い finale in く prima di qualunque aggiunta: 寒い (freddo) → 寒く + ない. ではない è solo per i nomi e gli aggettivi in な.'),
  ('fba6f22c-731b-51d4-a33f-9b4f83ba8de9', '否定の-ない', 'single-select', '{"sentence":{"kanji":"この映画はよくない","kana":"このえいがはよくない"},"answer":"よくない","distractors":["いくない","いいない","よいない"],"gap":{"kanji":"この映画は＿","kana":"このえいがは＿"},"prompt":{"en":"\"This film is not good.\" What is the negative of いい?","it":"«Questo film non è bello.» Qual è la negazione di いい?"}}'::jsonb, '形容詞の否定「くない」', 'いい (good) has an older form, よい, and every change is built on that one: "not good" is よくない and "was good" is よかった. いくない does not exist.', 'いい (buono) ha una forma più antica, よい, e ogni trasformazione si costruisce su quella: «non buono» è よくない e «era buono» è よかった. いくない non esiste.'),
  ('b340d16c-bcce-5281-806c-2f88c74cfb10', '否定の-ない', 'assemble', '{"sentence":{"kanji":"昨日は雨が降らなかった","kana":"きのうはあめがふらなかった"},"answer":["昨日は","雨が","降らなかった"],"prompt":{"en":"Build: \"It did not rain yesterday.\"","it":"Componi: «Ieri non è piovuto.»"}}'::jsonb, '否定の「ない」', 'Since a negative verb ends in the adjective ない, its past follows the adjective rule: drop い, add かった. 降る → 降らない → 降らなかった, "it did not rain".', 'Poiché un verbo negato finisce con l''aggettivo ない, il suo passato segue la regola degli aggettivi: si toglie い e si aggiunge かった. 降る → 降らない → 降らなかった, «non è piovuto».'),
  ('a1216140-12ce-5d2a-935e-ab787b263c95', '否定の-ない', 'select-span', '{"sentence":{"kanji":"テレビを見なかった","kana":"テレビをみなかった"},"answer":{"start":2,"end":3},"prompt":{"en":"Which part is the past negative ending?","it":"Quale parte è la desinenza negativa al passato?"}}'::jsonb, '否定の「ない」', 'Select the past negative ending: なかった. 見る is an ichidan verb, so ない attaches after removing る: 見ない; then ない goes into the past like any い-adjective: 見なかった.', 'Seleziona la desinenza negativa passata: なかった. 見る è un verbo ichidan, quindi ない si attacca dopo aver tolto る: 見ない; poi ない va al passato come qualunque aggettivo in い: 見なかった.'),
  ('52bf43ea-e519-5318-be37-3953bf03d7be', '否定の-ない', 'single-select', '{"sentence":{"kanji":"私はたばこを吸いません","kana":"わたしはたばこをすいません"},"answer":"吸いません","distractors":["吸わません","吸うません","吸いまさない"],"gap":{"kanji":"私はたばこを＿","kana":"わたしはたばこを＿"},"prompt":{"en":"\"I don''t smoke.\" (polite) What is the polite negative of 吸う?","it":"«Non fumo.» (cortese) Qual è la negazione cortese di 吸う?"}}'::jsonb, '丁寧な否定「ません」', 'The polite ending ます attaches to the i-stem (吸う → 吸い) and, unlike the other endings, does not use ない for its negative: it becomes ません. So 吸います → 吸いません.', 'La desinenza cortese ます si attacca al radicale in i (吸う → 吸い) e, a differenza delle altre desinenze, non usa ない per negarsi: diventa ません. Quindi 吸います → 吸いません.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('890ece21-e470-5522-9007-238149cdf418', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"毎週手紙を書きます","kana":"まいしゅうてがみをかきます"},"answer":"書きます","distractors":["書くます","書かます","書こます"],"gap":{"kanji":"毎週手紙を＿","kana":"まいしゅうてがみを＿"},"prompt":{"en":"\"I write a letter every week.\" What is the polite form of 書く?","it":"«Ogni settimana scrivo una lettera.» Qual è la forma cortese di 書く?"}}'::jsonb, '連用形につく「ます」「たい」', 'The polite auxiliary ます attaches to the i-stem: the final u-row kana moves to the i-row. 書く → 書き + ます. It changes the register, not the meaning.', 'L''ausiliare cortese ます si attacca al radicale in i: l''ultimo kana della riga in u passa alla riga in i. 書く → 書き + ます. Cambia il registro, non il significato.'),
  ('9c01efa2-0480-512a-b7ec-ace89c604eb4', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"ゆっくり休みたい","kana":"ゆっくりやすみたい"},"answer":"休みたい","distractors":["休むたい","休またい","休みったい"],"gap":{"kanji":"ゆっくり＿","kana":"ゆっくり＿"},"prompt":{"en":"\"I want to rest properly.\" How do you say \"want to rest\"?","it":"«Voglio riposarmi con calma.» Come si dice «voler riposare»?"}}'::jsonb, '連用形につく「ます」「たい」', 'たい (want to) also attaches to the i-stem: 休む → 休み + たい. Unlike ます it is an い-adjective, so it is negated and put in the past like one: 休みたくない, 休みたかった.', 'Anche たい (voler fare) si attacca al radicale in i: 休む → 休み + たい. A differenza di ます è un aggettivo in い, quindi si nega e va al passato come tale: 休みたくない, 休みたかった.'),
  ('cb90a02a-6d35-5b29-ae38-611a76e319d3', '動詞の語幹と助動詞', 'assemble', '{"sentence":{"kanji":"一緒に昼ごはんを食べましょう","kana":"いっしょにひるごはんをたべましょう"},"answer":["一緒に","昼ごはんを","食べましょう"],"prompt":{"en":"Build: \"Let''s have lunch together.\"","it":"Componi: «Pranziamo insieme.»"}}'::jsonb, '連用形につく「ます」「たい」', 'ましょう is the volitional of ます, "let''s" in the polite register. Like ます, it goes on the i-stem; for the ichidan verb 食べる, the stem is simply 食べ.', 'ましょう è il volitivo di ます, «facciamo» nel registro cortese. Come ます, va sul radicale in i; per il verbo ichidan 食べる, il radicale è semplicemente 食べ.'),
  ('5fd847ca-3b86-509a-94eb-615047363693', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"先生が生徒に本を読ませた","kana":"せんせいがせいとにほんをよませた"},"answer":"読ませた","distractors":["読みせた","読むさせた","読めさせた"],"gap":{"kanji":"先生が生徒に本を＿","kana":"せんせいがせいとにほんを＿"},"prompt":{"en":"\"The teacher had the pupils read a book.\" What is the causative past of 読む?","it":"«L''insegnante ha fatto leggere un libro agli studenti.» Qual è il causativo passato di 読む?"}}'::jsonb, '未然形につく「せる」「れる」', 'The causative (make or let someone do) attaches せる to the a-stem of a godan verb: 読む → 読ま + せる. The person made to act is marked by に: the teacher had the pupils read a book.', 'Il causativo (far fare o lasciar fare) attacca せる al radicale in a di un verbo godan: 読む → 読ま + せる. La persona fatta agire è marcata da に: l''insegnante ha fatto leggere un libro agli studenti.'),
  ('82a7d415-c9cc-5d00-8d43-37bb64d9afd1', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"母が子供に野菜を食べさせた","kana":"ははがこどもにやさいをたべさせた"},"answer":"食べさせた","distractors":["食べせた","食べらせた","食べませた"],"gap":{"kanji":"母が子供に野菜を＿","kana":"ははがこどもにやさいを＿"},"prompt":{"en":"\"The mother made the child eat vegetables.\" What is the causative past of 食べる?","it":"«La madre ha fatto mangiare le verdure al bambino.» Qual è il causativo passato di 食べる?"}}'::jsonb, '未然形につく「せる」「れる」', 'An ichidan verb loses る and takes the longer form of the auxiliary, させる: 食べる → 食べさせる. Where an auxiliary has two forms, the longer one always goes on ichidan verbs.', 'Un verbo ichidan perde る e prende la forma più lunga dell''ausiliare, させる: 食べる → 食べさせる. Quando un ausiliare ha due forme, la più lunga va sempre sui verbi ichidan.'),
  ('60424dec-be6d-5efb-a460-98282ec99bf0', '動詞の語幹と助動詞', 'select-span', '{"sentence":{"kanji":"財布を盗まれた","kana":"さいふをぬすまれた"},"answer":{"start":1,"end":2},"prompt":{"en":"Which part turns 盗む into a passive past?","it":"Quale parte trasforma 盗む in un passivo al passato?"}}'::jsonb, '未然形につく「せる」「れる」', 'Select まれた: the a-stem ま of 盗む (steal), the passive auxiliary れる, and the past た. The passive also attaches to the a-stem (ichidan verbs take られる): "(my) wallet was stolen", with the victim left as an unspoken subject.', 'Seleziona まれた: il radicale in a ま di 盗む (rubare), l''ausiliare passivo れる e il passato た. Anche il passivo si attacca al radicale in a (i verbi ichidan prendono られる): «mi hanno rubato il portafoglio», con la vittima come soggetto sottinteso.'),
  ('219d9482-5afc-5f6c-bddf-de8c75155efa', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"一緒に帰ろう","kana":"いっしょにかえろう"},"answer":"帰ろう","distractors":["帰りよう","帰るう","帰よう"],"gap":{"kanji":"一緒に＿","kana":"いっしょに＿"},"prompt":{"en":"\"Let''s go home together.\" What is the volitional of 帰る?","it":"«Torniamo a casa insieme.» Qual è il volitivo di 帰る?"}}'::jsonb, '意向形', 'The volitional ("let''s") moves the final kana to the o-row and adds う, which lengthens the vowel: 帰る → 帰ろう. 帰る ends in -eru but is godan, so it does not take よう.', 'Il volitivo («facciamo») sposta l''ultimo kana alla riga in o e aggiunge う, che allunga la vocale: 帰る → 帰ろう. 帰る finisce in -eru ma è godan, quindi non prende よう.'),
  ('83685bf3-6246-59cf-b37c-fb267e5680a3', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"そろそろ始めよう","kana":"そろそろはじめよう"},"answer":"始めよう","distractors":["始めろう","始めおう","始まよう"],"gap":{"kanji":"そろそろ＿","kana":"そろそろ＿"},"prompt":{"en":"\"Let''s get started.\" What is the volitional of 始める?","it":"«Cominciamo.» Qual è il volitivo di 始める?"}}'::jsonb, '意向形', 'Ichidan verbs make the volitional by removing る and adding よう: 始める (begin) → 始めよう, "let''s get started".', 'I verbi ichidan formano il volitivo togliendo る e aggiungendo よう: 始める (cominciare) → 始めよう, «cominciamo».')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('65ce9fba-80c4-5be5-a3d4-bdcd2dc6b00f', '目的地を示す-に', 'assemble', '{"sentence":{"kanji":"図書館に本を借りに行く","kana":"としょかんにほんをかりにいく"},"answer":["図書館に","本を","借りに","行く"],"prompt":{"en":"Build: \"I go to the library to borrow a book.\"","it":"Componi: «Vado in biblioteca a prendere in prestito un libro.»"}}'::jsonb, '目的を示す「に」', 'The sentence has two に: 図書館に is the place you go to, 借りに is the purpose of going. The i-stem 借り works as a noun ("borrowing"), so it can take に: "I go to the library to borrow a book".', 'La frase ha due に: 図書館に è il luogo in cui si va, 借りに è lo scopo dell''andare. Il radicale in i 借り funziona come un nome («il prendere in prestito»), quindi può prendere に: «vado in biblioteca a prendere in prestito un libro».'),
  ('6fd6cdc9-b3a2-595a-a61b-b9601056c094', '目的地を示す-に', 'single-select', '{"sentence":{"kanji":"海に泳ぎに行った","kana":"うみにおよぎにいった"},"answer":"泳ぎに","distractors":["泳ぐに","泳いに","泳ぎで"],"gap":{"kanji":"海に＿行った","kana":"うみに＿いった"},"prompt":{"en":"\"I went to the sea to swim.\" How do you say \"to swim\" (purpose)?","it":"«Sono andato al mare a nuotare.» Come si dice «a nuotare» (scopo)?"}}'::jsonb, '目的を示す「に」', 'Purpose with a verb of movement is the i-stem plus に: 泳ぐ → 泳ぎ + に. The purpose に attaches to a noun, and the i-stem is the noun form of the verb; the dictionary form 泳ぐ cannot take に here.', 'Lo scopo con un verbo di movimento è il radicale in i più に: 泳ぐ → 泳ぎ + に. Il に di scopo si attacca a un nome, e il radicale in i è la forma nominale del verbo; la forma del dizionario 泳ぐ qui non può prendere に.'),
  ('f8fe3190-e688-51fe-83d9-b05fe9c9fdc5', '目的地を示す-に', 'single-select', '{"sentence":{"kanji":"猫が庭にいる","kana":"ねこがにわにいる"},"answer":"に","distractors":["で","を"],"gap":{"kanji":"猫が庭＿いる","kana":"ねこがにわ＿いる"},"prompt":{"en":"\"The cat is in the garden.\" Which particle marks where the cat is?","it":"«Il gatto è in giardino.» Quale particella marca dove si trova il gatto?"}}'::jsonb, '存在の場所を示す「に」', 'The place where someone or something is — with いる for living beings, ある for things — is marked by に. で is for the place where an action happens, and いる is not an action.', 'Il luogo in cui qualcuno o qualcosa si trova — con いる per gli esseri viventi, ある per le cose — è marcato da に. で serve per il luogo in cui avviene un''azione, e いる non è un''azione.'),
  ('ff2cd48a-e2f0-5e68-ae7d-5db0bcfc73f1', '目的地を示す-に', 'select-span', '{"sentence":{"kanji":"ここに傘がある","kana":"ここにかさがある"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part says where the umbrella is?","it":"Quale parte dice dove si trova l''ombrello?"}}'::jsonb, '存在の場所を示す「に」', 'Select the location: ここに. The umbrella is the subject of ある (there is), and に marks where it is. When ある or いる say where something or someone is, the place is marked by に, not で.', 'Seleziona il luogo: ここに. L''ombrello è il soggetto di ある (c''è), e に marca dove si trova. Quando ある o いる dicono dove si trova qualcosa o qualcuno, il luogo è marcato da に, non da で.'),
  ('369af471-99a9-5cf0-a96d-b23acb38413b', '目的地を示す-に', 'single-select', '{"sentence":{"kanji":"兄は医者になった","kana":"あにはいしゃになった"},"answer":"に","distractors":["を","で"],"gap":{"kanji":"兄は医者＿なった","kana":"あにはいしゃ＿なった"},"prompt":{"en":"\"My older brother became a doctor.\" Which particle marks what he became?","it":"«Mio fratello maggiore è diventato medico.» Quale particella marca ciò che è diventato?"}}'::jsonb, '変化の結果を示す「に」', 'なる means "become", and the result of the change is marked by に: 医者になった, "became a doctor". With a noun or a な-adjective, the result normally takes に.', 'なる significa «diventare», e il risultato del cambiamento è marcato da に: 医者になった, «è diventato medico». Con un nome o un aggettivo in な, il risultato prende normalmente に.'),
  ('dd21cd3e-299e-5f96-9c2c-04ebcfb63da1', '目的地を示す-に', 'single-select', '{"sentence":{"kanji":"部屋が明るくなった","kana":"へやがあかるくなった"},"answer":"明るく","distractors":["明るいに","明るに","明るいく"],"gap":{"kanji":"部屋が＿なった","kana":"へやが＿なった"},"prompt":{"en":"\"The room became bright.\" Which form of 明るい goes before なる?","it":"«La stanza è diventata luminosa.» Quale forma di 明るい va davanti a なる?"}}'::jsonb, '変化の結果を示す「に」', 'に attaches to nouns, and 明るい (bright) is an い-adjective. Before なる, an い-adjective changes its final い into く: 明るくなった, "became bright".', 'に si attacca ai nomi, e 明るい (luminoso) è un aggettivo in い. Davanti a なる, un aggettivo in い cambia la い finale in く: 明るくなった, «è diventato luminoso».'),
  ('76e29e2e-d600-5905-8028-5b2f911e6d34', '目的地を示す-に', 'single-select', '{"sentence":{"kanji":"来月京都へ行く","kana":"らいげつきょうとへいく"},"answer":"へ","distractors":["が","の"],"gap":{"kanji":"来月京都＿行く","kana":"らいげつきょうと＿いく"},"prompt":{"en":"\"Next month I''m going to Kyoto.\" Which particle marks the direction?","it":"«Il mese prossimo vado a Kyoto.» Quale particella marca la direzione?"}}'::jsonb, '方向を示す「へ」', 'The particle へ, pronounced え, marks the direction of a movement. Of the uses of に in this lesson, it overlaps only with the destination, so here に would also be correct. へ cannot mark where something is: 庭へいる is wrong.', 'La particella へ, pronunciata え, marca la direzione di un movimento. Tra gli usi di に visti in questa lezione, si sovrappone solo alla destinazione, quindi qui anche に sarebbe corretto. へ non può marcare dove si trova qualcosa: 庭へいる è sbagliato.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('d176c834-1d3d-5076-864b-72adb47f4948', '動作の場所を示す-で', 'single-select', '{"sentence":{"kanji":"図書館で勉強する","kana":"としょかんでべんきょうする"},"answer":"で","distractors":["に","を"],"gap":{"kanji":"図書館＿勉強する","kana":"としょかん＿べんきょうする"},"prompt":{"en":"\"I study at the library.\" Which particle marks where the action happens?","it":"«Studio in biblioteca.» Quale particella marca dove avviene l''azione?"}}'::jsonb, '動作の場所を示す「で」', 'Studying is an action, and the place where an action takes place is marked by で. に would name a place you go to or are at, not the scene of an activity.', 'Studiare è un''azione, e il luogo in cui si svolge un''azione è marcato da で. に indicherebbe un luogo in cui si va o in cui ci si trova, non la scena di un''attività.'),
  ('e12190eb-47b7-5eab-b513-73b09b4713aa', '動作の場所を示す-で', 'single-select', '{"sentence":{"kanji":"姉は台所にいる","kana":"あねはだいどころにいる"},"answer":"に","distractors":["で","を"],"gap":{"kanji":"姉は台所＿いる","kana":"あねはだいどころ＿いる"},"prompt":{"en":"\"My older sister is in the kitchen.\" Which particle marks where she is?","it":"«Mia sorella maggiore è in cucina.» Quale particella marca dove si trova?"}}'::jsonb, '動作の場所を示す「で」', 'Here nothing is being done: いる only says where the sister is, so the place takes に. Compare 台所で料理する, "cooks in the kitchen", where an action calls for で.', 'Qui non si fa nulla: いる dice solo dove si trova la sorella, quindi il luogo prende に. Si confronti con 台所で料理する, «cucina in cucina», dove un''azione richiede で.'),
  ('52e10f75-c252-59df-b6a8-d4362bae79a6', '動作の場所を示す-で', 'select-span', '{"sentence":{"kanji":"ペンで名前を書いた","kana":"ペンでなまえをかいた"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part says what was used to write?","it":"Quale parte dice con che cosa si è scritto?"}}'::jsonb, '手段を示す「で」', 'Select the means: ペンで. Besides the place of an action, で marks the tool or means used to do it: "wrote the name with a pen". The name is the object (を).', 'Seleziona il mezzo: ペンで. Oltre al luogo di un''azione, で marca lo strumento o il mezzo con cui la si compie: «ha scritto il nome con la penna». Il nome è l''oggetto (を).'),
  ('4c9bdd6a-99e8-52b1-9dd1-e1df78cda4d4', '動作の場所を示す-で', 'assemble', '{"sentence":{"kanji":"自転車で学校に通う","kana":"じてんしゃでがっこうにかよう"},"answer":["自転車で","学校に","通う"],"prompt":{"en":"Build: \"I go to school by bicycle.\"","it":"Componi: «Vado a scuola in bicicletta.»"}}'::jsonb, '手段を示す「で」', 'A means of transport is a means like any other, so it takes で: 自転車で, "by bicycle". The destination of the commute is marked by に.', 'Un mezzo di trasporto è un mezzo come un altro, quindi prende で: 自転車で, «in bicicletta». La destinazione del tragitto è marcata da に.'),
  ('0bfa5305-e678-52b2-be6c-c6a0e5b761d8', '動作の場所を示す-で', 'single-select', '{"sentence":{"kanji":"英語で手紙を書いた","kana":"えいごでてがみをかいた"},"answer":"で","distractors":["を","が"],"gap":{"kanji":"英語＿手紙を書いた","kana":"えいご＿てがみをかいた"},"prompt":{"en":"\"I wrote a letter in English.\" Which particle marks the language used?","it":"«Ho scritto una lettera in inglese.» Quale particella marca la lingua usata?"}}'::jsonb, '手段を示す「で」', 'A language used to say or write something is a means, so it takes で: 英語で, "in English". The letter is already the object with を, and a verb has only one object.', 'Una lingua usata per dire o scrivere qualcosa è un mezzo, quindi prende で: 英語で, «in inglese». La lettera è già l''oggetto con を, e un verbo ha un solo oggetto.'),
  ('8369e4be-0eaf-5345-8615-b6b8d8a98d93', '動作の場所を示す-で', 'single-select', '{"sentence":{"kanji":"パンと牛乳を買った","kana":"パンとぎゅうにゅうをかった"},"answer":"と","distractors":["を","へ"],"gap":{"kanji":"パン＿牛乳を買った","kana":"パン＿ぎゅうにゅうをかった"},"prompt":{"en":"\"I bought bread and milk.\" Which particle joins the two nouns?","it":"«Ho comprato pane e latte.» Quale particella unisce i due nomi?"}}'::jsonb, '名詞をつなぐ「と」', 'と joins nouns into a list: パンと牛乳, "bread and milk". It says nothing about their role in the sentence; the を after the last noun makes the whole list the object of 買った.', 'と unisce i nomi in un elenco: パンと牛乳, «pane e latte». Non dice nulla del loro ruolo nella frase; il を dopo l''ultimo nome rende l''intero elenco oggetto di 買った.'),
  ('dd3ffd65-32ba-5b83-b664-6ed29a402cdb', '動作の場所を示す-で', 'assemble', '{"sentence":{"kanji":"兄と弟が川で泳いでいる","kana":"あにとおとうとがかわでおよいでいる"},"answer":["兄と","弟が","川で","泳いでいる"],"prompt":{"en":"Build: \"My older and younger brothers are swimming in the river.\"","it":"Componi: «Il fratello maggiore e il minore stanno nuotando nel fiume.»"}}'::jsonb, '名詞をつなぐ「と」', '兄と弟 is one unit, "older and younger brother", and が after it marks both as the subject. 川で is where the swimming happens: an action, so で.', '兄と弟 è un''unica unità, «il fratello maggiore e il minore», e が dopo di essa li marca entrambi come soggetto. 川で è dove avviene il nuotare: un''azione, quindi で.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
