  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('53fc7beb-c295-5291-89ec-7310f54c0e85', '感情-理解の述語と-が', 'single-select', '{"sentence":{"kanji":"私は犬が好きだ","kana":"わたしはいぬがすきだ"},"answer":"が","distractors":["を","で"],"gap":{"kanji":"私は犬＿好きだ","kana":"わたしはいぬ＿すきだ"},"prompt":{"en":"\"I like dogs.\" Which particle marks what is liked?","it":"«Mi piacciono i cani.» Quale particella marca ciò che piace?"}}'::jsonb, '感情・理解の述語と「が」', '好き is not a verb: it is a な-adjective, a noun that closes the sentence with だ. A verb takes its object with を, but 好きだ does not have an object, so what is liked is marked by が. The person who likes it is the topic, 私は.', '好き non è un verbo: è un aggettivo in な, un nome che chiude la frase con だ. Un verbo prende il suo oggetto con を, ma 好きだ non ha un oggetto, quindi ciò che piace è marcato da が. Chi prova il gusto è il tema, 私は.'),
  ('e3af00c5-e946-563c-bbf1-d525bb7067c2', '感情-理解の述語と-が', 'single-select', '{"sentence":{"kanji":"弟は漢字が分かる","kana":"おとうとはかんじがわかる"},"answer":"が","distractors":["を","で"],"gap":{"kanji":"弟は漢字＿分かる","kana":"おとうとはかんじ＿わかる"},"prompt":{"en":"\"My younger brother understands kanji.\" Which particle marks what is understood?","it":"«Mio fratello minore capisce i kanji.» Quale particella marca ciò che si capisce?"}}'::jsonb, '感情・理解の述語と「が」', '分かる describes a state — something is clear, understandable — not an action done to an object. What is understood is therefore marked by が, never by を: 漢字が分かる. The person is the topic, 弟は.', '分かる descrive uno stato — qualcosa è chiaro, comprensibile — non un''azione compiuta su un oggetto. Ciò che si capisce è quindi marcato da が, mai da を: 漢字が分かる. La persona è il tema, 弟は.'),
  ('f8a17f20-6a3c-5b1f-abde-422365eb833a', '感情-理解の述語と-が', 'assemble', '{"sentence":{"kanji":"新しい自転車がほしい","kana":"あたらしいじてんしゃがほしい"},"answer":["新しい","自転車が","ほしい"],"prompt":{"en":"Build: \"I want a new bicycle.\"","it":"Componi: «Voglio una bicicletta nuova.»"}}'::jsonb, '欲求の「ほしい」と「たい」', 'ほしい (wanted) ends in い: it is an adjective, not a verb. The thing wanted is marked by が. With no one else named, the feeling is the speaker''s: "I want a new bicycle".', 'ほしい (desiderato) finisce in い: è un aggettivo, non un verbo. La cosa desiderata è marcata da が. Se non si nomina nessun altro, il sentimento è di chi parla: «voglio una bicicletta nuova».'),
  ('cfc027a4-598d-522e-aeff-53f35b8f2e4f', '感情-理解の述語と-が', 'select-span', '{"sentence":{"kanji":"ラーメンが食べたい","kana":"ラーメンがたべたい"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part is the thing that is wanted?","it":"Quale parte è la cosa desiderata?"}}'::jsonb, '欲求の「ほしい」と「たい」', 'Select what is desired: ラーメンが. 食べたい is the i-stem 食べ plus the adjective たい, so, like any adjective, it takes が for the thing it is about. With を (ラーメンを食べたい) the sentence is also correct, but が is the more traditional choice.', 'Seleziona ciò che si desidera: ラーメンが. 食べたい è il radicale in i 食べ più l''aggettivo たい, quindi, come ogni aggettivo, prende が per la cosa di cui parla. Anche con を (ラーメンを食べたい) la frase è corretta, ma が è la scelta più tradizionale.'),
  ('9c045dfa-041f-5013-ac0a-02f0d02c79ed', '感情-理解の述語と-が', 'single-select', '{"sentence":{"kanji":"妹が新しいゲームをほしがっている","kana":"いもうとがあたらしいゲームをほしがっている"},"answer":"ほしがっている","distractors":["ほしい","ほしいだ","ほしくている"],"gap":{"kanji":"妹が新しいゲームを＿","kana":"いもうとがあたらしいゲームを＿"},"prompt":{"en":"\"My younger sister wants a new game.\" How do you describe someone else''s wish?","it":"«Mia sorella minore vuole un gioco nuovo.» Come si descrive il desiderio di un altro?"}}'::jsonb, '他人の感情を示す「がる」', 'ほしい and たい state the speaker''s own feelings: you cannot state someone else''s inner feeling as a fact. For another person you drop the final い and add the verb がる, "shows signs of": ほしがる. As a verb, it takes its object with を.', 'ほしい e たい esprimono i sentimenti di chi parla: il sentimento interiore di un altro non si può affermare come un fatto. Per un''altra persona si toglie la い finale e si aggiunge il verbo がる, «mostra segni di»: ほしがる. Essendo un verbo, prende l''oggetto con を.'),
  ('433e230a-0f7d-5b8b-9da7-1f844e6d758c', '感情-理解の述語と-が', 'single-select', '{"sentence":{"kanji":"子供が外で遊びたがっている","kana":"こどもがそとであそびたがっている"},"answer":"遊びたがっている","distractors":["遊びたい","遊びたいだ","遊ぶたがっている"],"gap":{"kanji":"子供が外で＿","kana":"こどもがそとで＿"},"prompt":{"en":"\"The child wants to play outside.\" How do you describe the child''s wish?","it":"«Il bambino vuole giocare fuori.» Come si descrive il desiderio del bambino?"}}'::jsonb, '他人の感情を示す「がる」', 'The child is not the speaker, so 遊びたい cannot describe the child''s wish directly. たい drops its い and takes がる: 遊びたがる, "is showing that they want to play", here in the ongoing form 遊びたがっている.', 'Il bambino non è chi parla, quindi 遊びたい non può descrivere direttamente il suo desiderio. たい perde la い e prende がる: 遊びたがる, «mostra di voler giocare», qui nella forma in corso 遊びたがっている.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('b1fa153e-1704-5115-b2ea-fcb8cb5e0483', '可能形', 'single-select', '{"sentence":{"kanji":"この川で泳げる","kana":"このかわでおよげる"},"answer":"泳げる","distractors":["泳ぎる","泳ぐれる","泳げられる"],"gap":{"kanji":"この川で＿","kana":"このかわで＿"},"prompt":{"en":"\"You can swim in this river.\" What is the potential of 泳ぐ?","it":"«In questo fiume si può nuotare.» Qual è il potenziale di 泳ぐ?"}}'::jsonb, '可能形', 'A godan verb forms the potential by moving its final kana to the e-row and adding る: 泳ぐ → 泳げ + る, "can swim". The result is an ordinary ichidan verb.', 'Un verbo godan forma il potenziale spostando l''ultimo kana alla riga in e e aggiungendo る: 泳ぐ → 泳げ + る, «si può nuotare». Il risultato è un normale verbo ichidan.'),
  ('e2e3e4f9-6c89-55ea-a10b-e438b2cbfa7c', '可能形', 'single-select', '{"sentence":{"kanji":"この魚は生で食べられる","kana":"このさかなはなまでたべられる"},"answer":"食べられる","distractors":["食べえる","食べらる","食べされる"],"gap":{"kanji":"この魚は生で＿","kana":"このさかなはなまで＿"},"prompt":{"en":"\"This fish can be eaten raw.\" What is the potential of 食べる?","it":"«Questo pesce si può mangiare crudo.» Qual è il potenziale di 食べる?"}}'::jsonb, '可能形', 'An ichidan verb removes る and adds られる: 食べる → 食べられる, "can be eaten". In casual speech you will also hear 食べれる, but 食べられる is the standard form.', 'Un verbo ichidan toglie る e aggiunge られる: 食べる → 食べられる, «si può mangiare». Nel parlato informale si sente anche 食べれる, ma 食べられる è la forma standard.'),
  ('86dd7435-ccdf-554c-951f-5a0c3815cda7', '可能形', 'single-select', '{"sentence":{"kanji":"兄は中国語ができる","kana":"あにはちゅうごくごができる"},"answer":"できる","distractors":["するれる","しれる","すられる"],"gap":{"kanji":"兄は中国語が＿","kana":"あにはちゅうごくごが＿"},"prompt":{"en":"\"My older brother can speak Chinese.\" What is the potential of する?","it":"«Mio fratello maggiore sa il cinese.» Qual è il potenziale di する?"}}'::jsonb, '不規則動詞の可能形', 'する is irregular and its potential is a separate verb: できる. What is possible is marked by が: 中国語ができる, "Chinese is within (his) ability" — he can speak Chinese.', 'する è irregolare e il suo potenziale è un verbo a sé: できる. Ciò che è possibile è marcato da が: 中国語ができる, «il cinese è alla sua portata» — sa parlare cinese.'),
  ('84c9b0a0-3ca9-517a-801b-c339fed2146e', '可能形', 'select-span', '{"sentence":{"kanji":"ひらがなが読める","kana":"ひらがながよめる"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part is the thing that can be read?","it":"Quale parte è ciò che si riesce a leggere?"}}'::jsonb, '可能形と「が」', 'Select the phrase marked by が: ひらがなが. A potential verb describes a state — something is readable — so the thing that can be read usually takes が rather than を. The person who can read it stays unspoken or appears as the topic with は.', 'Seleziona l''espressione marcata da が: ひらがなが. Un verbo potenziale descrive uno stato — qualcosa è leggibile — quindi la cosa che si può leggere di solito prende が invece di を. Chi sa leggere resta sottinteso o compare come tema con は.'),
  ('b3a6d49e-13cf-516e-a87e-a19b5e30bcfd', '可能形', 'single-select', '{"sentence":{"kanji":"昨日はよく眠れなかった","kana":"きのうはよくねむれなかった"},"answer":"眠れなかった","distractors":["眠りれなかった","眠るなかった","眠れないかった"],"gap":{"kanji":"昨日はよく＿","kana":"きのうはよく＿"},"prompt":{"en":"\"I couldn''t sleep well yesterday.\" How do you say \"couldn''t sleep\"?","it":"«Ieri non sono riuscito a dormire bene.» Come si dice «non sono riuscito a dormire»?"}}'::jsonb, '可能形', 'Since the potential is an ichidan verb, it negates and goes into the past like one: 眠れる → 眠れない → 眠れなかった, "(I) couldn''t sleep well".', 'Poiché il potenziale è un verbo ichidan, si nega e va al passato come tale: 眠れる → 眠れない → 眠れなかった, «non sono riuscito a dormire bene».'),
  ('03e003e9-bc42-5550-98fa-1a83f70cbce6', '可能形', 'assemble', '{"sentence":{"kanji":"日曜日は友達に会えない","kana":"にちようびはともだちにあえない"},"answer":["日曜日は","友達に","会えない"],"prompt":{"en":"Build: \"On Sunday I can''t meet my friends.\"","it":"Componi: «Domenica non posso vedere i miei amici.»"}}'::jsonb, '可能形', '会う (meet) → 会える (can meet) → 会えない (cannot meet). The person you meet is marked by に. 日曜日 is the topic here, so it takes は instead of に.', '会う (incontrare) → 会える (poter incontrare) → 会えない (non poter incontrare). La persona che si incontra è marcata da に. 日曜日 qui è il tema, quindi prende は invece di に.'),
  ('0239c596-9ece-5ceb-a7fb-7bd19a34c098', '可能形', 'single-select', '{"sentence":{"kanji":"明日は来られる","kana":"あしたはこられる"},"answer":"来られる","distractors":["来えれる","来れられる","来られれる"],"gap":{"kanji":"明日は＿","kana":"あしたは＿"},"prompt":{"en":"\"I can come tomorrow.\" What is the potential of 来る?","it":"«Domani posso venire.» Qual è il potenziale di 来る?"}}'::jsonb, '不規則動詞の可能形', 'The other irregular verb, 来る, has the potential 来られる (read こられる), "can come". Together with できる for する, these are the only two potentials that break the regular pattern.', 'L''altro verbo irregolare, 来る, ha il potenziale 来られる (letto こられる), «poter venire». Insieme a できる per する, sono gli unici due potenziali che rompono lo schema regolare.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('8b92cea7-e170-59d5-af03-0d9948f66eec', 'て形で節をつなぐ', 'assemble', '{"sentence":{"kanji":"朝ごはんを食べて学校に行った","kana":"あさごはんをたべてがっこうにいった"},"answer":["朝ごはんを","食べて","学校に","行った"],"prompt":{"en":"Build: \"I ate breakfast and went to school.\"","it":"Componi: «Ho fatto colazione e sono andato a scuola.»"}}'::jsonb, 'て形で節をつなぐ', 'The te-form ends a clause and announces that another one follows: "ate breakfast and went to school". The te-form carries no tense of its own; the past た at the end of the sentence applies to both actions.', 'La forma in て chiude una proposizione e annuncia che ne segue un''altra: «ho fatto colazione e sono andato a scuola». La forma in て non porta un tempo proprio; il passato た in fondo alla frase vale per entrambe le azioni.'),
  ('5037d864-083c-5c3d-babd-d31145d5d7c1', 'て形で節をつなぐ', 'single-select', '{"sentence":{"kanji":"窓を開けて外を見た","kana":"まどをあけてそとをみた"},"answer":"開けて","distractors":["開けって","開きて","開けるて"],"gap":{"kanji":"窓を＿外を見た","kana":"まどを＿そとをみた"},"prompt":{"en":"\"I opened the window and looked outside.\" Which form of 開ける joins the two actions?","it":"«Ho aperto la finestra e ho guardato fuori.» Quale forma di 開ける unisce le due azioni?"}}'::jsonb, 'て形で節をつなぐ', '開ける (open) is ichidan: remove る and add て, 開けて. The first clause (opened the window) is joined to the second (looked outside); only the last verb, 見た, shows that both happened in the past.', '開ける (aprire) è ichidan: si toglie る e si aggiunge て, 開けて. La prima proposizione (ho aperto la finestra) si unisce alla seconda (ho guardato fuori); solo l''ultimo verbo, 見た, mostra che entrambe sono avvenute nel passato.'),
  ('ade2203c-7d24-5132-8eb2-3fd07457c52b', 'て形で節をつなぐ', 'single-select', '{"sentence":{"kanji":"友達が私の宿題を手伝ってくれた","kana":"ともだちがわたしのしゅくだいをてつだってくれた"},"answer":"くれた","distractors":["あげた"],"gap":{"kanji":"友達が私の宿題を手伝って＿","kana":"ともだちがわたしのしゅくだいをてつだって＿"},"prompt":{"en":"\"A friend helped me with my homework.\" Which verb says the favour was done for me?","it":"«Un amico mi ha aiutato con i compiti.» Quale verbo dice che il favore è stato fatto a me?"}}'::jsonb, '恩恵を受ける「てくれる」', 'te-form + くれる means someone does something for the speaker or the speaker''s side: the friend helped with my homework, as a favour to me. あげる points the other way, from the speaker''s side to others, so it cannot be used when the benefit comes to me.', 'forma in て + くれる significa che qualcuno fa qualcosa per chi parla o per la sua cerchia: l''amico mi ha aiutato con i compiti, come favore a me. あげる va nella direzione opposta, da chi parla verso gli altri, quindi non si può usare quando il beneficio arriva a me.'),
  ('c2fb3ce9-039f-5f33-81e5-87058ea852c3', 'て形で節をつなぐ', 'select-span', '{"sentence":{"kanji":"父が夕飯を作ってくれた","kana":"ちちがゆうはんをつくってくれた"},"answer":{"start":1,"end":2},"prompt":{"en":"Which part says the dinner was made for the speaker?","it":"Quale parte dice che la cena è stata preparata per chi parla?"}}'::jsonb, '恩恵を受ける「てくれる」', 'Select ってくれた: the te-form ending of 作る followed by くれた. It tells you the dinner was made for the speaker''s benefit — "my father made dinner for me" — without any word for "for me".', 'Seleziona ってくれた: la desinenza in て di 作る seguita da くれた. Dice che la cena è stata preparata a beneficio di chi parla — «mio padre mi ha preparato la cena» — senza bisogno di una parola per «per me».'),
  ('9cfd0154-9276-5de8-8f67-efcf5be968fe', 'て形で節をつなぐ', 'single-select', '{"sentence":{"kanji":"私は妹に絵本を読んであげた","kana":"わたしはいもうとにえほんをよんであげた"},"answer":"あげた","distractors":["くれた"],"gap":{"kanji":"私は妹に絵本を読んで＿","kana":"わたしはいもうとにえほんをよんで＿"},"prompt":{"en":"\"I read a picture book to my younger sister.\" Which verb says I did it for her?","it":"«Ho letto un libro illustrato a mia sorella minore.» Quale verbo dice che l''ho fatto per lei?"}}'::jsonb, '恩恵を与える「てあげる」', 'te-form + あげる means the speaker (or someone) does something for another person: I read a picture book to my younger sister, for her sake. くれる is reserved for favours that come toward the speaker.', 'forma in て + あげる significa che chi parla (o qualcuno) fa qualcosa per un''altra persona: ho letto un libro illustrato a mia sorella minore, per lei. くれる è riservato ai favori che arrivano verso chi parla.'),
  ('25d90831-d6f2-5de8-9121-c357c506b9c6', 'て形で節をつなぐ', 'assemble', '{"sentence":{"kanji":"兄は忙しくて手伝ってくれなかった","kana":"あにはいそがしくててつだってくれなかった"},"answer":["兄は","忙しくて","手伝ってくれなかった"],"prompt":{"en":"Build: \"My older brother was busy and didn''t help me.\"","it":"Componi: «Mio fratello maggiore era impegnato e non mi ha aiutato.»"}}'::jsonb, '恩恵を受ける「てくれる」', 'An い-adjective has a te-form too: 忙しい → 忙しくて, here giving the reason, "was busy, and so…". The second clause is the negative past of てくれる: my brother did not help me. The single tense marker at the end covers both clauses.', 'Anche un aggettivo in い ha una forma in て: 忙しい → 忙しくて, qui a indicare il motivo, «era impegnato, e così…». La seconda proposizione è il passato negativo di てくれる: mio fratello non mi ha aiutato. L''unico segnale di tempo, in fondo, vale per entrambe le proposizioni.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

